CREATE TABLE patients (id {PK}, full_name TEXT NOT NULL, date_of_birth TEXT, phone TEXT, email TEXT, area TEXT, address_enc TEXT, status TEXT NOT NULL DEFAULT 'active', created_by BIGINT REFERENCES users(id), created_at TEXT NOT NULL);
CREATE INDEX idx_patients_name ON patients(full_name);
CREATE TABLE portal_accounts (id {PK}, email TEXT NOT NULL UNIQUE, full_name TEXT NOT NULL, phone TEXT, password_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', must_change_password INTEGER NOT NULL DEFAULT 0, consent_at TEXT NOT NULL, created_at TEXT NOT NULL, last_login_at TEXT, reviewed_by BIGINT REFERENCES users(id), reviewed_at TEXT);
CREATE TABLE patient_access (id {PK}, account_id BIGINT NOT NULL REFERENCES portal_accounts(id), patient_id BIGINT NOT NULL REFERENCES patients(id), relationship TEXT NOT NULL, consent_note TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', granted_by BIGINT NOT NULL REFERENCES users(id), granted_at TEXT NOT NULL, UNIQUE (account_id, patient_id));
CREATE TABLE appointments (id {PK}, patient_id BIGINT NOT NULL REFERENCES patients(id), requested_by_account BIGINT REFERENCES portal_accounts(id), requested_by_user BIGINT REFERENCES users(id), service TEXT NOT NULL, preferred_date TEXT, preferred_time TEXT, reason TEXT, status TEXT NOT NULL DEFAULT 'requested', scheduled_at TEXT, staff_note TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by BIGINT REFERENCES users(id));
CREATE INDEX idx_appt_patient ON appointments(patient_id);
